package runtime

import (
	"bytes"
	"context"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// TestGoldenCPythonOutput runs each testdata/*.py script and requires its
// output to match the sibling .out file, which was generated by CPython 3.
func TestGoldenCPythonOutput(t *testing.T) {
	scripts, err := filepath.Glob(filepath.Join("..", "..", "testdata", "*.py"))
	if err != nil || len(scripts) == 0 {
		t.Skip("no golden scripts found")
	}
	for _, script := range scripts {
		want, err := os.ReadFile(strings.TrimSuffix(script, ".py") + ".out")
		if err != nil {
			continue // not a golden test
		}
		src, err := os.ReadFile(script)
		if err != nil {
			t.Fatal(err)
		}
		t.Run(filepath.Base(script), func(t *testing.T) {
			var buf bytes.Buffer
			rt := New(Config{Stdout: &buf})
			if err := rt.RunString(context.Background(), string(src), script); err != nil {
				t.Fatalf("script failed: %v", err)
			}
			got := buf.String()
			if got == string(want) {
				return
			}
			gl, wl := strings.Split(got, "\n"), strings.Split(string(want), "\n")
			for i := 0; i < len(gl) && i < len(wl); i++ {
				if gl[i] != wl[i] {
					t.Fatalf("first difference at line %d:\n got: %s\nwant: %s", i+1, gl[i], wl[i])
				}
			}
			t.Fatalf("output length differs: got %d lines, want %d", len(gl), len(wl))
		})
	}
}
